SELECT 100.0 * SUM(CASE WHEN LOWER(c.colour) = 'blue' THEN 1 ELSE 0 END) / NULLIF(COUNT(*),0) AS percentage_blue_eyes
FROM superhero s
LEFT JOIN colour c ON s.eye_colour_id = c.id;
